    `${border}│\x1B[0m${padVisual(urlLine, boxInner)}${border}│\x1B[0m`,
    `${border}│\x1B[0m${padVisual(beforeLine, boxInner)}${border}│\x1B[0m`,
    `${border}│\x1B[0m${padVisual(afterLine, boxInner)}${border}│\x1B[0m`,
    `${border}└${bottomDashes}┘\x1B[0m`
